use mradm_dsp::hptf::{Band, BandKind, PreampMode, Processor, Snapshot, design};
use std::time::Instant;

fn profile() -> Vec<Band> {
    let kinds = [
        BandKind::LowShelf,
        BandKind::Peaking,
        BandKind::Peaking,
        BandKind::Peaking,
        BandKind::Peaking,
        BandKind::Peaking,
        BandKind::Peaking,
        BandKind::Peaking,
        BandKind::Peaking,
        BandKind::HighShelf,
    ];
    let f = [
        105., 46., 180., 420., 900., 1700., 3100., 5200., 7800., 10000.,
    ];
    let g = [9.7, -9.2, 2.1, -1.8, 3.3, -4.4, 5.0, -2.9, 1.7, -2.2];
    let q = [0.7, 0.37, 1.1, 0.9, 1.6, 2.2, 3.1, 2.4, 1.3, 0.7];
    (0..10)
        .map(|i| Band {
            kind: kinds[i],
            enabled: true,
            frequency: f[i],
            gain_db: g[i],
            q: q[i],
        })
        .collect()
}

#[test]
fn zz_bench() {
    let bands = profile();
    let mut design_us = Vec::new();
    let mut process_ms = Vec::new();
    for _ in 0..21 {
        let start = Instant::now();
        for _ in 0..200 {
            std::hint::black_box(design(&bands, -6.0, 48000, PreampMode::AutoTrim).unwrap());
        }
        design_us.push(start.elapsed().as_secs_f64() * 1e6 / 200.0);
        let c = design(&bands, -6.0, 48000, PreampMode::AutoTrim).unwrap();
        let mut p = Processor::new(2, 48000).unwrap();
        p.reset(Some(Snapshot {
            coefficients: c,
            revision: 1,
        }))
        .unwrap();
        let mut pcm: Vec<f32> = (0..48000 * 20 * 2)
            .map(|i| ((i as f32) * 0.001).sin() * 0.3)
            .collect();
        let start = Instant::now();
        for block in pcm.chunks_mut(511 * 2) {
            p.process(block, None).unwrap();
        }
        process_ms.push(start.elapsed().as_secs_f64() * 1e3);
        std::hint::black_box(&pcm);
    }
    design_us.sort_by(f64::total_cmp);
    process_ms.sort_by(f64::total_cmp);
    println!(
        "BENCH design_us_median {:.1} process_20s_ms_median {:.2}",
        design_us[10], process_ms[10]
    );
}
